var state = msg.payload.toUpperCase();
var label, color;
if      (state === 'EMERGENCY') { label = 'EMERGENCY'; color = '#ff0000'; }
else if (state === 'WARNING')   { label = 'WARNING';   color = '#ff8000'; }
else                            { label = 'NORMAL';    color = '#00b500'; }

msg.payload  = label;
msg.ui_update = {color: color};
return msg;
